{
  "items": [
    {
      "name": "MvPolynomial.eval₂_id",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {g : σ → R} (p : MvPolynomial σ R) : MvPolynomial.eval₂ (RingHom.id R) g p = (MvPolynomial.eval g) p",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.eval₂_comp",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] (f : R →+* S₁) (g : σ → R) (p : MvPolynomial σ R) : f ((MvPolynomial.eval g) p) = MvPolynomial.eval₂ f (⇑f ∘ g) p",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.eval_map",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] (f : R →+* S₁) (g : σ → S₁) (p : MvPolynomial σ R) : (MvPolynomial.eval g) ((MvPolynomial.map f) p) = MvPolynomial.eval₂ f g p",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.eval₂_eq_eval_map",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] (f : R →+* S₁) (g : σ → S₁) (p : MvPolynomial σ R) : MvPolynomial.eval₂ f g p = (MvPolynomial.eval g) ((MvPolynomial.map f) p)",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.eval_eval₂",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {S : Type u_2} {τ : Type u_3} {x : τ → S} [CommSemiring S] (f : R →+* MvPolynomial τ S) (g : σ → MvPolynomial τ S) (p : MvPolynomial σ R) : (MvPolynomial.eval x) (MvPolynomial.eval₂ f g p) = MvPolynomial.eval₂ ((MvPolynomial.eval x).comp f) (fun s => (MvPolynomial.eval x) (g s)) p",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.eval_assoc",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {τ : Type u_2} (f : σ → MvPolynomial τ R) (g : τ → R) (p : MvPolynomial σ R) : (MvPolynomial.eval (⇑(MvPolynomial.eval g) ∘ f)) p = (MvPolynomial.eval g) (MvPolynomial.eval₂ MvPolynomial.C f p)",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    }
  ]
}
